import SwiftUI
import SyncSpaceKit

struct IOSDevicesView: View { @EnvironmentObject private var state: SyncSpaceAppState
    var body: some View { List { if !state.pairingRequests.isEmpty { Section("Pairing requests") { ForEach(state.pairingRequests) { request in VStack(alignment: .leading) { Text(request.deviceName ?? "Unknown device").font(.headline); if let code = request.verificationCode { Text("Verification code: \(code)").font(.system(.body, design: .monospaced)) } } } } }; Section("Nearby devices") { if state.discoveredDevices.isEmpty { ContentUnavailableView("No nearby devices", systemImage: "antenna.radiowaves.left.and.right") } else { ForEach(state.discoveredDevices) { device in NavigationLink { IOSDeviceDetailView(device: device) } label: { DeviceRow(device: device) } } } }; Section("Trusted devices") { ForEach(state.trustedDevices) { trusted in Label(trusted.name, systemImage: trusted.blocked ? "hand.raised.fill" : "checkmark.shield.fill") } } }.navigationTitle("Devices").refreshable { await state.refreshDiscovery() } }
}
struct IOSDeviceDetailView: View { let device: Device; var body: some View { List { Section { DeviceRow(device: device); LabeledContent("Address", value: "\(device.host):\(device.port)"); LabeledContent("Version", value: device.version.isEmpty ? "Unknown" : device.version) }; Section("Actions") { Button("Pair", systemImage: "link") {}.disabled(device.isTrusted || !device.isOnline); Button("Send clipboard", systemImage: "doc.on.clipboard") {}.disabled(true); Button("Send note", systemImage: "note.text") {}.disabled(true); Button("Send file", systemImage: "paperclip") {}.disabled(true); Button("Forget device", systemImage: "trash", role: .destructive) {}.disabled(!device.isTrusted) } }.navigationTitle(device.name) } }
